import { X } from "lucide-react";
import { type ReactNode, type RefObject, useEffect, useRef } from "react";
import { createPortal } from "react-dom";

import { t, type UiText } from "../i18n";
import { cn } from "../lib/cn";
import { isComposingNativeKeyEvent } from "./Combobox";
import IconButton from "./IconButton";

function focusableElements(container: HTMLElement): HTMLElement[] {
  return Array.from(
    container.querySelectorAll<HTMLElement>(
      'button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])',
    ),
  ).filter((element) => !element.hasAttribute("hidden"));
}

/**
 * ModalFrame は確認・選択の窓の共通の骨組みである。フォーカスの取り込み・Esc での閉じ方・背景の inert 化を持ち、
 * 設定画面のフォルダ選択・削除の確認とタグ管理画面の確認の窓が共有する。
 */
export function ModalFrame({
  title,
  onClose,
  children,
  initialFocus,
  width = "sm:max-w-2xl",
}: {
  title: UiText;
  onClose: () => void;
  children: ReactNode;
  initialFocus?: RefObject<HTMLElement | null>;
  /** `sm` 以上の窓の最大幅（Tailwind の `sm:max-w-*`）。`sm` 未満は画面幅いっぱい。 */
  width?: "sm:max-w-2xl" | "sm:max-w-lg";
}) {
  const panel = useRef<HTMLDivElement>(null);
  const overlay = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const titleId = `dialog-${title.replaceAll(" ", "-")}`;

  useEffect(() => {
    const previous =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const background = Array.from(document.body.children).filter(
      (element) => element !== overlay.current,
    );
    const states = background.map((element) => ({
      element,
      inert: element.hasAttribute("inert"),
      ariaHidden: element.getAttribute("aria-hidden"),
    }));
    for (const element of background) {
      element.setAttribute("inert", "");
      element.setAttribute("aria-hidden", "true");
    }
    const keydown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") {
        // IME の変換中の Esc（変換候補の取り消し）は窓を閉じない（B2）。
        if (isComposingNativeKeyEvent(event)) return;
        // 窓の中の要素（Combobox の候補の一覧など）が既に Esc を処理して
        // preventDefault していれば、窓は閉じない。その要素自身が「一覧を
        // 閉じるだけ」か「窓を閉じる」かを決め、閉じる側は `onClose` を
        // 自分で呼ぶ（Combobox の `onEscapeWhenClosed` など。B1）。
        //
        // 「窓の中の要素が」に絞るのは、背景は inert のはずでも、フォーカスの
        // 復元（Radix のメニューなど）が inert を無視して背景の要素へ
        // フォーカスを戻すことがあり、その要素が自分の理由で Esc を
        // preventDefault していても、この窓の Esc とは無関係だからである。
        const insidePanel = panel.current?.contains(event.target as Node | null) ?? false;
        if (insidePanel && event.defaultPrevented) return;
        event.preventDefault();
        onCloseRef.current();
        return;
      }
      if (event.key !== "Tab" || panel.current === null) return;
      const elements = focusableElements(panel.current);
      if (elements.length === 0) return;
      const first = elements[0]!;
      const last = elements.at(-1)!;
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", keydown);
    return () => {
      document.removeEventListener("keydown", keydown);
      for (const state of states) {
        state.element.toggleAttribute("inert", state.inert);
        if (state.ariaHidden === null) state.element.removeAttribute("aria-hidden");
        else state.element.setAttribute("aria-hidden", state.ariaHidden);
      }
      queueMicrotask(() => previous?.focus());
    };
  }, []);

  useEffect(() => {
    const target = initialFocus?.current ?? focusableElements(panel.current!)[0];
    target?.focus();
  }, [initialFocus]);

  return createPortal(
    <div
      ref={overlay}
      className="fixed inset-0 z-50 flex items-stretch justify-center bg-overlay sm:items-center sm:p-6"
    >
      <div
        ref={panel}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className={cn(
          "flex min-h-0 w-full flex-col bg-elevated shadow-elevated sm:max-h-[calc(100dvh-3rem)] sm:rounded-lg sm:border sm:border-border-strong",
          width,
        )}
      >
        <div className="flex h-14 shrink-0 items-center gap-3 border-b border-border px-4">
          <h2 id={titleId} className="min-w-0 flex-1 truncate text-base font-semibold">
            {title}
          </h2>
          <IconButton label={t.common.close} onClick={onClose} tooltip={false}>
            <X />
          </IconButton>
        </div>
        {children}
      </div>
    </div>,
    document.body,
  );
}

export default ModalFrame;
